<?php $pageTitle='Teacher Dashboard'; require_once __DIR__.'/../includes/header.php'; $tid=$pdo->prepare("SELECT id FROM teachers WHERE user_id=?");$tid->execute([user()['id']]);$tid=$tid->fetchColumn();$classes=$tid?$pdo->prepare("SELECT c.* FROM teacher_classes tc JOIN classes c ON c.id=tc.class_id WHERE tc.teacher_id=?") : null;if($classes){$classes->execute([$tid]);$classes=$classes->fetchAll();}else{$classes=[];} ?>
<h2>Teacher Dashboard</h2><div class="row g-3"><div class="col-md-4"><div class="card p-4"><div class="text-muted">Assigned classes</div><div class="display-6"><?=count($classes)?></div></div></div><div class="col-md-8"><div class="card p-4"><h5>Announcements</h5><?php $a=$pdo->query("SELECT * FROM announcements WHERE audience IN ('all','teachers') AND (expires_at IS NULL OR expires_at>NOW()) ORDER BY published_at DESC LIMIT 5")->fetchAll();foreach($a as $x): ?><div class="border-bottom py-2"><strong><?=e($x['title'])?></strong><div><?=nl2br(e($x['body']))?></div></div><?php endforeach;?></div></div></div>
